<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/header.php';
if($_SESSION['user']['role']!=='admin'){http_response_code(403);die('Access denied');}$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$s=$pdo->prepare("SELECT COUNT(*) bills,COALESCE(SUM(total),0) sales FROM bills WHERE DATE(created_at) BETWEEN ? AND ?");$s->execute([$from,$to]);$sales=$s->fetch();$s=$pdo->prepare("SELECT COALESCE(SUM(amount),0) paid FROM payments WHERE DATE(paid_at) BETWEEN ? AND ?");$s->execute([$from,$to]);$paid=$s->fetch()['paid'];$s=$pdo->prepare("SELECT COALESCE(SUM(amount),0) expenses FROM expenses WHERE expense_date BETWEEN ? AND ?");$s->execute([$from,$to]);$exp=$s->fetch()['expenses'];$net=$paid-$exp;$s=$pdo->prepare("SELECT p.category,SUM(bi.quantity) qty,SUM(bi.line_total) total FROM bill_items bi JOIN bills b ON b.id=bi.bill_id JOIN products p ON p.id=bi.product_id WHERE DATE(b.created_at) BETWEEN ? AND ? GROUP BY p.category ORDER BY total DESC");$s->execute([$from,$to]);$cats=$s->fetchAll();?><h2>Reports</h2><div class="card"><form method="get" class="grid"><div><label>From</label><input type="date" name="from" value="<?=e($from)?>"></div><div><label>To</label><input type="date" name="to" value="<?=e($to)?>"></div><div><label>&nbsp;</label><button>Filter</button></div></form></div><div class="grid"><div class="card">Bills<br><div class="stat"><?=number_format($sales['bills'])?></div></div><div class="card">Sales<br><div class="stat">TSh <?=number_format($sales['sales'])?></div></div><div class="card">Paid<br><div class="stat">TSh <?=number_format($paid)?></div></div><div class="card">Expenses<br><div class="stat">TSh <?=number_format($exp)?></div></div><div class="card">Net Cash<br><div class="stat">TSh <?=number_format($net)?></div></div></div><br><div class="card"><h3>Sales by Category</h3><table><tr><th>Category</th><th>Quantity</th><th>Total</th></tr><?php foreach($cats as $c):?><tr><td><?=e($c['category'])?></td><td><?=e($c['qty'])?></td><td>TSh <?=number_format($c['total'])?></td></tr><?php endforeach;?></table></div><?php require_once __DIR__.'/../config/footer.php';?>
